const http = require("http");
const zlib = require("zlib");
const tcb = require("@cloudbase/node-sdk");

const app = tcb.init({
  env: process.env.CLOUDBASE_ENV_ID || process.env.TCB_ENV,
  accessKey: process.env.COLORBOX__ACCESS_KEY
});
const rdb = app.rdb({ database: "public" });
const RESULT_TABLE = "result_poster_results";

function apiPath(req) {
  const pathname = new URL(req.url, "http://localhost").pathname || "/";
  return pathname.replace(/^\/api(?=\/|$)/, "") || "/";
}

function readPuid(req) {
  const raw = req.headers["x-cloudbase-context"];
  if (!raw) {
    const error = new Error("请先登录");
    error.statusCode = 401;
    throw error;
  }
  let buffer = Buffer.from(String(raw).trim(), "base64");
  if (buffer.length >= 2 && buffer[0] === 0x1f && buffer[1] === 0x8b) {
    buffer = zlib.gunzipSync(buffer);
  }
  const context = JSON.parse(buffer.toString("utf8"));
  const puid = context.customUserId || context.userId || context.uid;
  if (!puid) {
    const error = new Error("请先登录");
    error.statusCode = 401;
    throw error;
  }
  return String(puid);
}

function queryRows(result) {
  if (!result) return [];
  if (Array.isArray(result)) return result;
  if (Array.isArray(result.data)) return result.data;
  if (Array.isArray(result.rows)) return result.rows;
  return [];
}

function getJsonBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 65536) reject(new Error("请求内容过大"));
    });
    req.on("end", () => {
      if (!body) return resolve({});
      try { resolve(JSON.parse(body)); } catch { reject(new Error("请求格式不正确")); }
    });
    req.on("error", reject);
  });
}

function resultData(row) {
  if (!row) return null;
  return {
    id: row.id,
    nickname: row.nickname,
    rank: Number(row.rank),
    score: Number(row.score),
    percentile: row.percentile,
    date: row.result_date,
    shareCount: Number(row.share_count || 0),
    updatedAt: row.updated_at
  };
}

async function getRdbServiceToken() {
  const credential = await app.auth().getClientCredential();
  if (typeof credential === "string" && credential.trim()) return credential.trim();
  if (credential && typeof credential.access_token === "string" && credential.access_token.trim()) {
    return credential.access_token.trim();
  }
  const accessKey = process.env.COLORBOX__ACCESS_KEY;
  if (accessKey && accessKey.trim()) return accessKey.trim();
  throw new Error("数据库服务凭据不可用");
}

async function saveResult(puid, payload) {
  const token = await getRdbServiceToken();
  const envId = process.env.CLOUDBASE_ENV_ID || process.env.TCB_ENV;
  const response = await fetch(
    `https://${envId}.api.tcloudbasegateway.com/v1/rdb/rest/rpc/save_result_poster_result`,
    {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${token}`,
        "X-Db-Instance": "default",
        "Accept-Profile": "public",
        "Content-Profile": "public",
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        p_puid: puid,
        p_nickname: payload.nickname,
        p_rank: payload.rank,
        p_score: payload.score,
        p_percentile: payload.percentile,
        p_result_date: payload.date
      })
    }
  );
  const raw = await response.text();
  let data = raw;
  try { data = raw ? JSON.parse(raw) : null; } catch { /* preserve text for logs */ }
  if (!response.ok) {
    console.error("[Result Poster RPC Error]", response.status, data);
    const error = new Error("结果暂时无法保存");
    error.statusCode = 500;
    throw error;
  }
  return Array.isArray(data) ? data[0] : data;
}

async function handle(req, res) {
  const headers = {
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Request-Id, X-CloudBase-Context",
    "Content-Type": "application/json; charset=utf-8"
  };
  if (req.method === "OPTIONS") {
    res.writeHead(204, headers);
    return res.end();
  }

  const path = apiPath(req);
  try {
    if (req.method === "GET" && path === "/health") {
      res.writeHead(200, headers);
      return res.end(JSON.stringify({ code: 0, message: "ok" }));
    }

    if (req.method === "GET" && path === "/result/me") {
      const puid = readPuid(req);
      const result = await rdb.from(RESULT_TABLE)
        .select("id, nickname, rank, score, percentile, result_date, share_count, updated_at")
        .eq("puid", puid)
        .limit(1);
      const rows = queryRows(result);
      res.writeHead(200, headers);
      return res.end(JSON.stringify({ code: 0, message: "success", data: resultData(rows[0]) }));
    }

    if (req.method === "POST" && path === "/result/save") {
      const puid = readPuid(req);
      const body = await getJsonBody(req);
      const rank = Number(body.rank);
      const score = Number(body.score);
      if (!Number.isSafeInteger(rank) || rank < 1 || rank > 2147483647) {
        const error = new Error("排名格式不正确");
        error.statusCode = 400;
        throw error;
      }
      if (!Number.isSafeInteger(score) || score < 0 || score > 2147483647) {
        const error = new Error("积分格式不正确");
        error.statusCode = 400;
        throw error;
      }
      const nickname = typeof body.nickname === "string" && body.nickname.trim()
        ? body.nickname.trim().slice(0, 40)
        : "Hupu User";
      const percentile = typeof body.percentile === "string" ? body.percentile.trim().slice(0, 20) : "";
      const date = typeof body.date === "string" ? body.date.trim().slice(0, 32) : "";
      const row = await saveResult(puid, { nickname, rank, score, percentile, date });
      res.writeHead(200, headers);
      return res.end(JSON.stringify({ code: 0, message: "success", data: resultData(row) }));
    }

    res.writeHead(404, headers);
    return res.end(JSON.stringify({ code: 404, message: "not found" }));
  } catch (error) {
    console.error("[Result Poster API Error]", error);
    const statusCode = error.statusCode || 500;
    const message = statusCode < 500 ? (error.message || "请求失败") : "服务暂时不可用";
    res.writeHead(statusCode, headers);
    return res.end(JSON.stringify({ code: statusCode, message }));
  }
}

http.createServer(handle).listen(process.env.PORT || 9000);

-- Reuse the platform demo table as the activity result source.
alter table public.demo_items rename to result_poster_results;
truncate table public.result_poster_results;

alter table public.result_poster_results
  alter column puid set not null,
  add column if not exists nickname text not null default 'Hupu User',
  add column if not exists rank integer not null default 0,
  add column if not exists score integer not null default 0,
  add column if not exists percentile text not null default '前 0%',
  add column if not exists result_date text not null default '',
  add column if not exists share_count integer not null default 0,
  add column if not exists updated_at timestamptz not null default now();

create unique index if not exists result_poster_results_puid_uidx
  on public.result_poster_results (puid);
create index if not exists result_poster_results_updated_idx
  on public.result_poster_results (updated_at desc, id asc);

alter table public.result_poster_results disable row level security;

create or replace function public.save_result_poster_result(
  p_puid text,
  p_nickname text,
  p_rank integer,
  p_score integer,
  p_percentile text,
  p_result_date text
)
returns public.result_poster_results
language plpgsql
security definer
set search_path = public
as $$
declare
  result public.result_poster_results;
begin
  insert into public.result_poster_results
    (puid, nickname, rank, score, percentile, result_date, created_at, updated_at)
  values
    (p_puid, p_nickname, p_rank, p_score, p_percentile, p_result_date, now(), now())
  on conflict (puid) do update
    set nickname = excluded.nickname,
        rank = excluded.rank,
        score = excluded.score,
        percentile = excluded.percentile,
        result_date = excluded.result_date,
        updated_at = now()
  returning * into result;

  return result;
end;
$$;

grant all on table public.result_poster_results to public;
grant usage on schema public to anon, authenticated, service_role, public;
grant select on table public.result_poster_results to anon, authenticated, service_role, public;
grant insert, update, delete on table public.result_poster_results to authenticated, service_role, public;
grant execute on function public.save_result_poster_result(text, text, integer, integer, text, text)
  to public, anon, authenticated, service_role;

# 结果海报发帖接口契约

## OSS 上传

```js
const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png', 0.92));
const response = await window.ColorboxAI.oss.uploadFile({
  file: blob,
  filename: `result-poster-${Date.now()}.png`
});
if (!response || !response.downloadUrl) throw new Error('海报上传失败');
```

`file` 必须是 HTML5 `File` 或 `Blob`。单文件不能超过 10MB；上传失败、未登录或返回缺少 `downloadUrl` 时立即结束分享流程。不要在页面保存 `authToken`，不要直连 OSS。

业务代码应在调用编辑器前用 `new URL(downloadUrl)` 校验返回值为带 hostname 的绝对 `https:` URL；不符合要求时停止流程，不得把不可信地址传给编辑器。

## 发帖编辑器

```js
const response = await window.ColorboxAI.request.bbs.openPostEditor({
  title: '我的活动结果',
  content: '我在本次活动中获得 1280 分，排名第 4。',
  imageUrl: uploadResponse.downloadUrl,
  topicId: undefined,
  tagId: undefined
});
if (!response || response.code !== 200) throw new Error(response?.message || '发帖编辑器打开失败');
```

只在用户主动点击分享按钮后调用。禁止用 `location`、`window.open` 或自拼 Schema 代替 SDK。`content` 可为字符串或富文本段落数组；结果正文应限制长度，避免把未校验的 HTML 当作富文本传入。

## 推荐流程

```text
结果数据 → Canvas 生成 PNG Blob → OSS uploadFile → 读取 downloadUrl
       → openPostEditor(title, content, imageUrl) → 展示成功/取消反馈
```

分享流程应可重复执行，但每次点击只能有一个进行中的上传/唤起操作。上传成功而编辑器失败时保留海报预览，并提示用户稍后重新点击分享；不要自动再次上传。
